insert into public.services (slug,title,summary,description,scope,inclusions,exclusions,duration_minutes,fee_pkr,fee_is_starting_price,fee_needs_review,is_active,refund_terms,sort_order) values
('visa-guidance-session', 'Visa Guidance Session', 'A 30-minute online consultation to understand your options and the general process.', 'A focused conversation about your travel, study or work goal. We explain the general visa categories that may apply, the usual document requirements and sensible next steps, using official sources as the reference.', 'Initial guidance and orientation only.', array['30-minute one-to-one online session', 'Overview of general visa options for your goal', 'Indicative document checklist based on official sources', 'Suggested next steps and official links']::text[], array['Submission of any application', 'Legal advice', 'Government, embassy or biometric fees', 'Any guarantee of a visa or immigration outcome']::text[], 30, 1500, false, true, true, 'Refund and cancellation conditions are set out in the Refund and Cancellation Policy (draft — pending owner approval).', 1),
('document-review', 'Document Review', 'A careful check of the documents you have prepared against the official checklist.', 'You prepare your documents; we review them against the published official requirements and tell you what looks complete, what may be missing and what to clarify before you apply.', 'Review and written feedback on documents prepared by you.', array['Review against the official checklist for your visa category', 'Written summary of gaps and suggestions', 'One follow-up clarification message']::text[], array['Preparing or translating documents on your behalf', 'Submitting the application', 'Government, embassy or biometric fees', 'Any guarantee of a visa or immigration outcome']::text[], null, 3500, false, true, true, 'Refund and cancellation conditions are set out in the Refund and Cancellation Policy (draft — pending owner approval).', 2),
('application-assistance', 'Application Assistance', 'Step-by-step help organising and completing your application. Availability pending regulatory review.', 'Practical help understanding the application form, organising supporting documents and preparing for submission. You remain the applicant and are responsible for the accuracy of everything you submit.', 'Guided assistance. Scope depends on destination and visa category.', array['Walk-through of the official application steps', 'Help organising supporting documents', 'Pre-submission checklist']::text[], array['Representing you before an embassy or authority', 'Government, embassy or biometric fees', 'Legal advice', 'Any guarantee of a visa or immigration outcome']::text[], null, 7500, true, true, false, 'Refund and cancellation conditions are set out in the Refund and Cancellation Policy (draft — pending owner approval).', 3)
